/// <summary>
/// PaffH 01.02.25
/// </summary>
/// <param name = "_contract">NDXBatchMultiThreadingContract</param>
/// <returns>NDXMultiThreadingCreateTaskController</returns>
public static NDXMultiThreadingCreateTaskController instance(NDXBatchMultiThreadingContract _contract = null)
{
    boolean lSGOC = false;   // use SysGlobalObjectCache to store instance ?
    NDXMultiThreadingCreateTaskUmsController singleton;
    NDXMultiThreadingCreateTaskControllerContract nDXMultiThreadingCreateTaskControllerContract = NDXMultiThreadingCreateTaskControllerContract::construct(_contract);
    nDXMultiThreadingCreateTaskControllerContract.parmNDXBatchProcessingType(
        _contract.parmUmsBasisLJ() ?
        NDXBatchProcessingType::SalesCurrentYear : NDXBatchProcessingType::SalesLastYear);

    SysGlobalObjectCache sgoc;
    container con;
    NDXBatchProcessingTableHeader nDXBatchProcessingTableHeader;
    if (lSGOC)
    {
        sgoc = ClassFactory.globalObjectCache();
        if (_contract.parmUmsBasisLJ())
        {
            singleton = NDXMultiThreadingCreateTaskUmsLJController::constructMinimal();
        }
        else
        {
            singleton = NDXMultiThreadingCreateTaskUmsVJController::constructMinimal();
        }
        con = sgoc.find(singleton.parmScope(), singleton.parmKey());
    }
    else
    {
        nDXBatchProcessingTableHeader = NDXBatchProcessingTableHeader::findSignature(_contract.parmSignature(), true);
        con = nDXBatchProcessingTableHeader.InstanceData;
    }
    NDXMultiThreadingCreateTaskUmsController nDXMultiThreadingCreateTaskUmsController;
    if(_contract.parmUmsBasisLJ())
    {
        nDXMultiThreadingCreateTaskUmsController = NDXMultiThreadingCreateTaskUmsLJController::construct();
    }
    else
    {
        nDXMultiThreadingCreateTaskUmsController = NDXMultiThreadingCreateTaskUmsVJController::construct();
    }

    if (con != conNull() && (!_contract || !_contract.parmNewControllerInstance()))  // existing instance or build new
    {
        nDXMultiThreadingCreateTaskControllerContract = NDXMultiThreadingCreateTaskControllerContract::contractFromContainer(con);
        singleton = NDXMultiThreadingCreateTaskController::construct(nDXMultiThreadingCreateTaskControllerContract, nDXMultiThreadingCreateTaskUmsController);
    }
    else
    {
        singleton = NDXMultiThreadingCreateTaskController::construct(nDXMultiThreadingCreateTaskControllerContract, nDXMultiThreadingCreateTaskUmsController);

        NDXMultiThreadingCreateTaskControllerContract contract = NDXMultiThreadingCreateTaskControllerContract::contractFromNDXMultiThreadingCreateTaskController(singleton);
        con = contract.contract2Container();
        if (lSGOC)
        {
            sgoc.insert(singleton.parmScope(), singleton.parmKey(), con);
        }
        else
        {
            if (!nDXBatchProcessingTableHeader)
            {
                nDXBatchProcessingTableHeader = NDXBatchProcessingTableHeader::findOrCreateFromContract(contract, false);
            }
            nDXBatchProcessingTableHeader.InstanceData = con;
            ttsbegin;
            nDXBatchProcessingTableHeader.write();
            ttscommit;
        }
    }
    //NDXMultiThreadingCreateTaskContract createTaskContract = singleton.getDataContractObject('_contract');
    //if (!createTaskContract)
    //{
    //    throw Error(strFmt("@SYS23264", classStr(NDXMultiThreadingCreateTaskContract)));
    //}
    //createTaskContract.parmUmsBasisLJ(nDXMultiThreadingCreateTaskControllerContract.parmUmsBasisLJ());
    //createTaskContract.parmSignatureUmsVJ(nDXMultiThreadingCreateTaskControllerContract.parmSignatureUmsVJ());

    return singleton;
}
